/* @autogenerated */
import { inject } from '@angular/core';
import { RedirectFunction, Routes, ROUTES } from '@angular/router';
import { AppStateService } from '@shared/context/state/app-state.service';
import { RuntimeConfigService, MicroFrontConfigService } from '@shared/context/config/app-config.service';
import { workspaceRoutes } from './workspace/workspace.routes';
import { WORKSPACE_LIST } from './workspaces.config';
import { UnknownComponent } from './layout/pages/unknown/unknown.component';
import { ContainerComponent } from './layout/pages/container/container.component';
import { urlContextGuard } from './url-context.guard';

export function provideConfiguredRoutes() {
  function initializeRoutes(appConfig: RuntimeConfigService, mfeConfig: MicroFrontConfigService) {
    return [
      {
        path: ':language/:tenant',
        component: ContainerComponent,
        // Antes que las guardas de las hijas: si redirigen, el destino ya usa el idioma de la URL
        canActivate: [urlContextGuard],
        runGuardsAndResolvers: 'paramsOrQueryParamsChange',
        children: aditioanlRoutes(appConfig, mfeConfig),
      },
      {
        // Sin pasar por un componente: no se ve nada mientras se redirige
        path: '',
        pathMatch: 'full',
        redirectTo: rootRedirect,
      },
      {
        path: '**',
        component: UnknownComponent,
      },
    ];
  }
  return {
    provide: ROUTES,
    useFactory: initializeRoutes,
    deps: [RuntimeConfigService, MicroFrontConfigService],
    multi: true,
  };
}

/** `/` lleva a la portada con el idioma y el tenant elegidos o, si no se han elegido, los de la configuración. */
export const rootRedirect: RedirectFunction = () => {
  const state = inject(AppStateService);
  return `/${state.language()}/${state.tenant()}`;
};

function aditioanlRoutes(appConfig: RuntimeConfigService, mfeConfig: MicroFrontConfigService): Routes {
  return [
    // Un workspace por segmento (`@admin/...`) y el de por defecto directamente bajo el tenant
    ...workspaceRoutes(WORKSPACE_LIST, appConfig, mfeConfig),
    {
      path: '**',
      component: UnknownComponent,
    },
  ];
}
